import{_ as p,a0 as o,w as d,s as r,I as n,x as a,a1 as e,A as t,ao as l}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const $=JSON.parse('{"title":"如何構建一台網絡引導服務器（一） | LCTT x X-CMD","titleTemplate":false,"description":"如何構建一台網絡引導服務器（一） | LCTT (201812) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何構建一台網絡引導服務器（一） | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何構建一台網絡引導服務器（一） | LCTT (201812) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201812/20181123 How to Build a Netboot Server, Part 1","title":"如何構建一台網絡引導服務器（一）","tag":"201812","desc":""},"relativePath":"201812/20181123 How to Build a Netboot Server, Part 1.md","filePath":"[post].md"}'),c={name:"201812/20181123 How to Build a Netboot Server, Part 1.md"};function h(g,s,k,u,b,f){const i=o("Link");return d(),r("div",null,[s[42]||(s[42]=n("h1",{id:"如何構建一台網絡引導服務器-一",tabindex:"-1"},[a("如何構建一台網絡引導服務器（一） "),n("a",{class:"header-anchor",href:"#如何構建一台網絡引導服務器-一","aria-label":"Permalink to “如何構建一台網絡引導服務器（一）”"},"​")],-1)),s[43]||(s[43]=n("p",null,[n("img",{src:"https://fedoramagazine.org/wp-content/uploads/2018/11/build-netboot-816x345.jpg",alt:""})],-1)),n("p",null,[s[1]||(s[1]=a("有些計算機網絡需要在各個物理機器上維護相同的軟件和配置。學校的計算機實驗室就是這樣的一個環境。 ",-1)),e(i,{href:"https://en.wikipedia.org/wiki/Network_booting"},{default:t(()=>[...s[0]||(s[0]=[a("網絡引導",-1)])]),_:1}),s[2]||(s[2]=a(" 服務器能夠被配置為基於網絡去提供一個完整的操作系統，以便於客户端計算機從一箇中央位置獲取配置。本教程將向你展示構建一台網絡引導服務器的一種方法。",-1))]),s[44]||(s[44]=n("p",null,"本教程的第一部分將包括創建一台網絡引導服務器和鏡像。第二部分將展示如何去添加 Kerberos 驗證的家目錄到網絡引導配置中。",-1)),s[45]||(s[45]=n("h3",{id:"初始化配置",tabindex:"-1"},[a("初始化配置 "),n("a",{class:"header-anchor",href:"#初始化配置","aria-label":"Permalink to “初始化配置”"},"​")],-1)),n("p",null,[s[4]||(s[4]=a("首先去下載 Fedora 服務器的 ",-1)),e(i,{href:"https://dl.fedoraproject.org/pub/fedora/linux/releases/28/Server/x86_64/iso/"},{default:t(()=>[...s[3]||(s[3]=[a("netinst",-1)])]),_:1}),s[5]||(s[5]=a(" 鏡像，將它刻錄到一張光盤上，然後用它引導服務器來重新格式化。我們只需要一個典型的 Fedora Server 的“最小化安裝”來作為我們的開端，安裝完成後，我們可以使用命令列去添加我們需要的任何額外的包。",-1))]),s[46]||(s[46]=l(`<p><img src="https://fedoramagazine.org/wp-content/uploads/2018/11/installation-summary-1024x768.png" alt=""></p><blockquote><p>注意：本教程中我們將使用 Fedora 28。其它版本在“最小化安裝”中包含的包可能略有不同。如果你使用的是不同的 Fedora 版本，如果一個預期的文件或命令不可用，你可能需要做一些調試。</p></blockquote><p>最小化安裝的 Fedora Server 運行起來之後，以 root 用户登入：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo -i</span></span></code></pre></div><p>並設置主機名字：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ MY_HOSTNAME=server-01.example.edu</span></span>
<span class="line"><span>$ hostnamectl set-hostname $MY_HOSTNAME</span></span></code></pre></div>`,6)),n("blockquote",null,[n("p",null,[s[7]||(s[7]=a("注意：Red Hat 建議靜態和臨時名字應都要與這個機器在 DNS 中的完全合格域名相匹配，比如 host.example.com（",-1)),e(i,{href:"https://docs.fedoraproject.org/en-US/Fedora/25/html/Networking_Guide/ch-Configure_Host_Names.html#sec_Understanding_Host_Names"},{default:t(()=>[...s[6]||(s[6]=[a("瞭解主機名字",-1)])]),_:1}),s[8]||(s[8]=a("）。",-1))]),s[9]||(s[9]=n("p",null,[a("注意：本指南為了方便“複製粘貼”。需要自定義的任何值都聲明為一個 "),n("code",null,"MY_*"),a(" 變量，在你運行剩餘命令之前，你可能需要調整它。如果你註銷之後，變量的賦值將被清除。")],-1)),s[10]||(s[10]=n("p",null,[a("注意：Fedora 28 Server 在默認情況下往往會轉儲大量的日誌到控制台上。你可以通過運行命令："),n("code",null,"sysctl -w kernel.printk=0"),a(" 去禁用控制台日誌輸出。")],-1))]),s[47]||(s[47]=l(`<p>接下來，我們需要在我們的服務器上配置一個靜態網絡地址。運行下面的一系列命令將找到並重新配置你的默認網絡連接：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ MY_DNS1=192.0.2.91</span></span>
<span class="line"><span>$ MY_DNS2=192.0.2.92</span></span>
<span class="line"><span>$ MY_IP=192.0.2.158</span></span>
<span class="line"><span>$ MY_PREFIX=24</span></span>
<span class="line"><span>$ MY_GATEWAY=192.0.2.254</span></span>
<span class="line"><span>$ DEFAULT_DEV=$(ip route show default | awk &#39;{print $5}&#39;)</span></span>
<span class="line"><span>$ DEFAULT_CON=$(nmcli d show $DEFAULT_DEV | sed -n &#39;/^GENERAL.CONNECTION:/s!.*:\\s*!! p&#39;)</span></span>
<span class="line"><span>$ nohup bash &lt;&lt; END</span></span>
<span class="line"><span>nmcli con mod &quot;$DEFAULT_CON&quot; connection.id &quot;$DEFAULT_DEV&quot;</span></span>
<span class="line"><span>nmcli con mod &quot;$DEFAULT_DEV&quot; connection.interface-name &quot;$DEFAULT_DEV&quot;</span></span>
<span class="line"><span>nmcli con mod &quot;$DEFAULT_DEV&quot; ipv4.method disabled</span></span>
<span class="line"><span>nmcli con up &quot;$DEFAULT_DEV&quot;</span></span>
<span class="line"><span>nmcli con add con-name br0 ifname br0 type bridge</span></span>
<span class="line"><span>nmcli con mod br0 bridge.stp no</span></span>
<span class="line"><span>nmcli con mod br0 ipv4.dns $MY_DNS1,$MY_DNS2</span></span>
<span class="line"><span>nmcli con mod br0 ipv4.addresses $MY_IP/$MY_PREFIX</span></span>
<span class="line"><span>nmcli con mod br0 ipv4.gateway $MY_GATEWAY</span></span>
<span class="line"><span>nmcli con mod br0 ipv4.method manual</span></span>
<span class="line"><span>nmcli con up br0</span></span>
<span class="line"><span>nmcli con add con-name br0-slave0 ifname &quot;$DEFAULT_DEV&quot; type bridge-slave master br0</span></span>
<span class="line"><span>nmcli con up br0-slave0</span></span>
<span class="line"><span>END</span></span></code></pre></div>`,2)),n("blockquote",null,[s[14]||(s[14]=n("p",null,[a("注意：上面最後的一組命令被封裝到一個 "),n("code",null,"nohup"),a(" 腳本中，因為它將臨時禁用網絡。這個 "),n("code",null,"nohup"),a(" 命令可以讓 "),n("code",null,"nmcli"),a(" 命令運行完成，即使你的 SSH 連接斷開。注意，連接恢復可能需要 10 秒左右的時間，如果你改變了服務器 IP 地址，你將需要重新啓動一個新的 SSH 連接。")],-1)),n("p",null,[s[12]||(s[12]=a("注意：上面的網絡配置在默認的連接之上創建了一個 ",-1)),e(i,{href:"https://en.wikipedia.org/wiki/Bridging_(networking)"},{default:t(()=>[...s[11]||(s[11]=[a("網橋",-1)])]),_:1}),s[13]||(s[13]=a("，這樣我們在後面的測試中就可以直接運行一個虛擬機實例。如果你不想在這台服務器上去直接測試網絡引導鏡像，你可以跳過創建網橋的命令，並直接在你的默認網絡連接上配置靜態 IP 地址。",-1))])]),s[48]||(s[48]=l('<h3 id="安裝和配置-nfs4" tabindex="-1">安裝和配置 NFS4 <a class="header-anchor" href="#安裝和配置-nfs4" aria-label="Permalink to “安裝和配置 NFS4”">​</a></h3><p>從安裝 nfs-utils 包開始：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ dnf install -y nfs-utils</span></span></code></pre></div>',3)),n("p",null,[s[16]||(s[16]=a("為發佈 NFS 去創建一個頂級的 ",-1)),e(i,{href:"https://www.centos.org/docs/5/html/5.1/Deployment_Guide/s3-nfs-server-config-exportfs-nfsv4.html"},{default:t(()=>[...s[15]||(s[15]=[a("偽文件系統",-1)])]),_:1}),s[17]||(s[17]=a("，然後在你的網絡上共享它：",-1))]),s[49]||(s[49]=l(`<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ MY_SUBNET=192.0.2.0</span></span>
<span class="line"><span>$ mkdir /export</span></span>
<span class="line"><span>$ echo &quot;/export -fsid=0,ro,sec=sys,root_squash $MY_SUBNET/$MY_PREFIX&quot; &gt; /etc/exports</span></span></code></pre></div><p>SELinux 會干擾網絡引導服務器的運行。為它配置例外規則超出了本教程中，因此我們這裏直接禁用它：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sed -i &#39;/GRUB_CMDLINE_LINUX/s/&quot;$/ audit=0 selinux=0&quot;/&#39; /etc/default/grub</span></span>
<span class="line"><span>$ grub2-mkconfig -o /boot/grub2/grub.cfg</span></span>
<span class="line"><span>$ sed -i &#39;s/SELINUX=enforcing/SELINUX=disabled/&#39; /etc/sysconfig/selinux</span></span>
<span class="line"><span>$ setenforce 0</span></span></code></pre></div><blockquote><p>注意：應該不需要編輯 grub 命令列，但我們在測試過程中發現，直接編輯 <code>/etc/sysconfig/selinux</code> 被證明重啓後是無效的，因此這樣做再次確保設置了 <code>selinux=0</code> 標誌。</p></blockquote><p>現在，在本地防火牆中為 NFS 服務添加一個例外規則，然後啓動 NFS 服務：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ firewall-cmd --add-service nfs</span></span>
<span class="line"><span>$ firewall-cmd --runtime-to-permanent</span></span>
<span class="line"><span>$ systemctl enable nfs-server.service</span></span>
<span class="line"><span>$ systemctl start nfs-server.service</span></span></code></pre></div><h3 id="創建網絡引導鏡像" tabindex="-1">創建網絡引導鏡像 <a class="header-anchor" href="#創建網絡引導鏡像" aria-label="Permalink to “創建網絡引導鏡像”">​</a></h3><p>現在我們的 NFS 服務器已經啓動運行了，我們需要為它提供一個操作系統鏡像，以便於它提供給客户端計算機。我們將從一個非常小的鏡像開始，等一切順利之後再添加。</p><p>首先，創建一個存放我們鏡像的新目錄：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ mkdir /fc28</span></span></code></pre></div><p>使用 <code>dnf</code> 命令在新目錄下用幾個基礎包去構建鏡像：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ dnf -y --releasever=28 --installroot=/fc28 install fedora-release systemd passwd rootfiles sudo dracut dracut-network nfs-utils vim-minimal dnf</span></span></code></pre></div><p>在上面的命令中省略了很重要的 <code>kernel</code> 包。在它們被安裝完成之前，我們需要去調整一下 <code>initramfs</code> 鏡像中包含的驅動程序集，<code>kernel</code> 首次安裝時將自動構建這個鏡像。尤其是，我們需要禁用 <code>hostonly</code> 模式，以便於 <code>initramfs</code> 鏡像能夠在各種硬件平台上正常工作，並且我們還需要添加對網絡和 NFS 的支持：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ echo &#39;hostonly=no&#39; &gt; /fc28/etc/dracut.conf.d/hostonly.conf</span></span>
<span class="line"><span>$ echo &#39;add_dracutmodules+=&quot; network nfs &quot;&#39; &gt; /fc28/etc/dracut.conf.d/netboot.conf</span></span></code></pre></div><p>現在，安裝 <code>kernel</code> 包：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ dnf -y --installroot=/fc28 install kernel</span></span></code></pre></div><p>設置一個阻止 <code>kernel</code> 包被更新的規則：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ echo &#39;exclude=kernel-*&#39; &gt;&gt; /fc28/etc/dnf/dnf.conf</span></span></code></pre></div><p>設置 locale：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ echo &#39;LANG=&quot;en_US.UTF-8&quot;&#39; &gt; /fc28/etc/locale.conf</span></span></code></pre></div><blockquote><p>注意：如果 locale 沒有正確配置，一些程序（如 GNOME Terminal）將無法正常工作。</p></blockquote><p>設置客户端的主機名字：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ MY_CLIENT_HOSTNAME=client-01.example.edu</span></span>
<span class="line"><span>$ echo $MY_CLIENT_HOSTNAME &gt; /fc28/etc/hostname</span></span></code></pre></div><p>禁用控制台日誌輸出：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ echo &#39;kernel.printk = 0 4 1 7&#39; &gt; /fc28/etc/sysctl.d/00-printk.conf</span></span></code></pre></div><p>定義網絡引導鏡像中的本地 <code>liveuser</code> 用户：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ echo &#39;liveuser:x:1000:1000::/home/liveuser:/bin/bash&#39; &gt;&gt; /fc28/etc/passwd</span></span>
<span class="line"><span>$ echo &#39;liveuser::::::::&#39; &gt;&gt; /fc28/etc/shadow</span></span>
<span class="line"><span>$ echo &#39;liveuser:x:1000:&#39; &gt;&gt; /fc28/etc/group</span></span>
<span class="line"><span>$ echo &#39;liveuser:!::&#39; &gt;&gt; /fc28/etc/gshadow</span></span></code></pre></div><p>允許 <code>liveuser</code> 使用 <code>sudo</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ echo &#39;liveuser ALL=(ALL) NOPASSWD: ALL&#39; &gt; /fc28/etc/sudoers.d/liveuser</span></span></code></pre></div><p>啓用自動創建家目錄：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ dnf install -y --installroot=/fc28 authselect oddjob-mkhomedir</span></span>
<span class="line"><span>$ echo &#39;dirs /home&#39; &gt; /fc28/etc/rwtab.d/home</span></span>
<span class="line"><span>$ chroot /fc28 authselect select sssd with-mkhomedir --force</span></span>
<span class="line"><span>$ chroot /fc28 systemctl enable oddjobd.service</span></span></code></pre></div><p>由於多個客户端將會同時掛載我們的鏡像，我們需要去配置鏡像工作在只讀模式中：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sed -i &#39;s/^READONLY=no$/READONLY=yes/&#39; /fc28/etc/sysconfig/readonly-root</span></span></code></pre></div><p>配置日誌輸出到內存而不是持久存儲中：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sed -i &#39;s/^#Storage=auto$/Storage=volatile/&#39; /fc28/etc/systemd/journald.conf</span></span></code></pre></div><p>配置 DNS：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ MY_DNS1=192.0.2.91</span></span>
<span class="line"><span>$ MY_DNS2=192.0.2.92</span></span>
<span class="line"><span>$ cat &lt;&lt; END &gt; /fc28/etc/resolv.conf</span></span>
<span class="line"><span>nameserver $MY_DNS1</span></span>
<span class="line"><span>nameserver $MY_DNS2</span></span>
<span class="line"><span>END</span></span></code></pre></div>`,37)),n("p",null,[s[19]||(s[19]=a("繞開編寫本教程時存在的根目錄只讀掛載的 bug（",-1)),e(i,{href:"https://bugzilla.redhat.com/show_bug.cgi?id=1542567"},{default:t(()=>[...s[18]||(s[18]=[a("BZ1542567",-1)])]),_:1}),s[20]||(s[20]=a("）：",-1))]),s[50]||(s[50]=l(`<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ echo &#39;dirs /var/lib/gssproxy&#39; &gt; /fc28/etc/rwtab.d/gssproxy</span></span>
<span class="line"><span>$ cat &lt;&lt; END &gt; /fc28/etc/rwtab.d/systemd</span></span>
<span class="line"><span>dirs /var/lib/systemd/catalog</span></span>
<span class="line"><span>dirs /var/lib/systemd/coredump</span></span>
<span class="line"><span>END</span></span></code></pre></div><p>最後，為我們鏡像創建 NFS 文件系統，並將它共享到我們的子網中：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ mkdir /export/fc28</span></span>
<span class="line"><span>$ echo &#39;/fc28 /export/fc28 none bind 0 0&#39; &gt;&gt; /etc/fstab</span></span>
<span class="line"><span>$ mount /export/fc28</span></span>
<span class="line"><span>$ echo &quot;/export/fc28 -ro,sec=sys,no_root_squash $MY_SUBNET/$MY_PREFIX&quot; &gt; /etc/exports.d/fc28.exports</span></span>
<span class="line"><span>$ exportfs -vr</span></span></code></pre></div><h3 id="創建引導加載器" tabindex="-1">創建引導加載器 <a class="header-anchor" href="#創建引導加載器" aria-label="Permalink to “創建引導加載器”">​</a></h3>`,4)),n("p",null,[s[22]||(s[22]=a("現在，我們已經有了可以進行網絡引導的操作系統，我們需要一個引導加載器去從客户端系統上啓動它。在本教程中我們使用的是 ",-1)),e(i,{href:"https://ipxe.org/"},{default:t(()=>[...s[21]||(s[21]=[a("iPXE",-1)])]),_:1}),s[23]||(s[23]=a("。",-1))]),s[51]||(s[51]=l(`<blockquote><p>注意：本節和接下來的節使用 QEMU 測試，也能在另外一台單獨的計算機上來完成；它們並不需要在網絡引導服務器上來運行。</p></blockquote><p>安裝 <code>git</code> 並使用它去下載 iPXE：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ dnf install -y git</span></span>
<span class="line"><span>$ git clone http://git.ipxe.org/ipxe.git $HOME/ipxe</span></span></code></pre></div><p>現在我們需要去為我們的引導加載器創建一個指定的啓動腳本：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cat &lt;&lt; &#39;END&#39; &gt; $HOME/ipxe/init.ipxe</span></span>
<span class="line"><span>#!ipxe</span></span>
<span class="line"><span></span></span>
<span class="line"><span>prompt --key 0x02 --timeout 2000 Press Ctrl-B for the iPXE command line... &amp;&amp; shell ||</span></span>
<span class="line"><span></span></span>
<span class="line"><span>dhcp || exit</span></span>
<span class="line"><span>set prefix file:///linux</span></span>
<span class="line"><span>chain \${prefix}/boot.cfg || exit</span></span>
<span class="line"><span>END</span></span></code></pre></div><p>啓動 “file” 下載協議：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ echo &#39;#define DOWNLOAD_PROTO_FILE&#39; &gt; $HOME/ipxe/src/config/local/general.h</span></span></code></pre></div><p>安裝 C 編譯器以及相關的工具和庫：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ dnf groupinstall -y &quot;C Development Tools and Libraries&quot;</span></span></code></pre></div><p>構建引導加載器：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cd $HOME/ipxe/src</span></span>
<span class="line"><span>$ make clean</span></span>
<span class="line"><span>$ make bin-x86_64-efi/ipxe.efi EMBED=../init.ipxe</span></span></code></pre></div><p>記下新編譯的引導加載器的存儲位置。我們將在接下來的節中用到它：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ IPXE_FILE=&quot;$HOME/ipxe/src/bin-x86_64-efi/ipxe.efi&quot;</span></span></code></pre></div><h3 id="用-qemu-測試" tabindex="-1">用 QEMU 測試 <a class="header-anchor" href="#用-qemu-測試" aria-label="Permalink to “用 QEMU 測試”">​</a></h3>`,14)),n("p",null,[s[25]||(s[25]=a("這一節是可選的，但是你需要去複製下面顯示在物理機器上的 ",-1)),e(i,{href:"https://en.wikipedia.org/wiki/EFI_system_partition"},{default:t(()=>[...s[24]||(s[24]=[a("EFI 系統分區",-1)])]),_:1}),s[26]||(s[26]=a(" 的佈局，在網絡引導時需要去配置它們。",-1))]),s[52]||(s[52]=l(`<blockquote><p>注意：如果你想實現一個完全的無盤系統，你也可以複製那個文件到一個 TFTP 服務器，然後從 DHCP 上指向那台服務器。</p></blockquote><p>為了使用 QEMU 去測試我們的引導加載器，我們繼續去創建一個僅包含一個 EFI 系統分區和我們的啓動文件的、很小的磁盤鏡像。</p><p>從創建 EFI 系統分區所需要的目錄佈局開始，然後把我們在前面節中創建的引導加載器複製進去：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ mkdir -p $HOME/esp/efi/boot</span></span>
<span class="line"><span>$ mkdir $HOME/esp/linux</span></span>
<span class="line"><span>$ cp $IPXE_FILE $HOME/esp/efi/boot/bootx64.efi</span></span></code></pre></div><p>下面的命令將識別我們的引導加載器鏡像正在使用的內核版本，並將它保存到一個變量中，以備後續的配置命令去使用它：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ DEFAULT_VER=$(ls -c /fc28/lib/modules | head -n 1)</span></span></code></pre></div><p>定義我們的客户端計算機將使用的引導配置：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ MY_DNS1=192.0.2.91</span></span>
<span class="line"><span>$ MY_DNS2=192.0.2.92</span></span>
<span class="line"><span>$ MY_NFS4=server-01.example.edu</span></span>
<span class="line"><span>$ cat &lt;&lt; END &gt; $HOME/esp/linux/boot.cfg</span></span>
<span class="line"><span>#!ipxe</span></span>
<span class="line"><span></span></span>
<span class="line"><span>kernel --name kernel.efi \\\${prefix}/vmlinuz-$DEFAULT_VER initrd=initrd.img ro ip=dhcp rd.peerdns=0 nameserver=$MY_DNS1 nameserver=$MY_DNS2 root=nfs4:$MY_NFS4:/fc28 console=tty0 console=ttyS0,115200n8 audit=0 selinux=0 quiet</span></span>
<span class="line"><span>initrd --name initrd.img \\\${prefix}/initramfs-$DEFAULT_VER.img</span></span>
<span class="line"><span>boot || exit</span></span>
<span class="line"><span>END</span></span></code></pre></div><blockquote><p>注意：上面的引導腳本展示瞭如何使用 iPXE 去網絡引導 Linux 的最小示例。還可以做更多更復雜的配置。值得注意的是，iPXE 支持交互式引導菜單，它可以讓你配置默認選項和超時時間。比如，一個更高級一點 iPXE 腳本可以默認從本地磁盤引導一個操作系統，如果在倒計時結束之前用户按下了一個鍵，才會去網絡引導一個操作系統。</p></blockquote><p>複製 Linux 內核並分配 initramfs 給 EFI 系統分區：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cp $(find /fc28/lib/modules -maxdepth 2 -name &#39;vmlinuz&#39; | grep -m 1 $DEFAULT_VER) $HOME/esp/linux/vmlinuz-$DEFAULT_VER</span></span>
<span class="line"><span>$ cp $(find /fc28/boot -name &#39;init*&#39; | grep -m 1 $DEFAULT_VER) $HOME/esp/linux/initramfs-$DEFAULT_VER.img</span></span></code></pre></div><p>我們最終的目錄佈局應該看起來像下面的樣子：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>esp</span></span>
<span class="line"><span>├── efi</span></span>
<span class="line"><span>│   └── boot</span></span>
<span class="line"><span>│   └── bootx64.efi</span></span>
<span class="line"><span>└── linux</span></span>
<span class="line"><span> ├── boot.cfg</span></span>
<span class="line"><span> ├── initramfs-4.18.18-200.fc28.x86_64.img</span></span>
<span class="line"><span> └── vmlinuz-4.18.18-200.fc28.x86_64</span></span></code></pre></div><p>要讓 QEMU 去使用我們的 EFI 系統分區，我們需要去創建一個小的 <code>uefi.img</code> 磁盤鏡像來包含它，然後將它連接到 QEMU 作為主引導驅動器。</p><p>開始安裝必需的工具：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ dnf install -y parted dosfstools</span></span></code></pre></div><p>現在創建 <code>uefi.img</code> 文件，並將 <code>esp</code> 目錄中的文件複製進去：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ESP_SIZE=$(du -ks $HOME/esp | cut -f 1)</span></span>
<span class="line"><span>$ dd if=/dev/zero of=$HOME/uefi.img count=$((\${ESP_SIZE}+5000)) bs=1KiB</span></span>
<span class="line"><span>$ UEFI_DEV=$(losetup --show -f $HOME/uefi.img)</span></span>
<span class="line"><span>$ parted \${UEFI_DEV} -s mklabel gpt mkpart EFI FAT16 1MiB 100% toggle 1 boot</span></span>
<span class="line"><span>$ mkfs -t msdos \${UEFI_DEV}p1</span></span>
<span class="line"><span>$ mkdir -p $HOME/mnt</span></span>
<span class="line"><span>$ mount \${UEFI_DEV}p1 $HOME/mnt</span></span>
<span class="line"><span>$ cp -r $HOME/esp/* $HOME/mnt</span></span>
<span class="line"><span>$ umount $HOME/mnt</span></span>
<span class="line"><span>$ losetup -d \${UEFI_DEV}</span></span></code></pre></div><blockquote><p>注意：在物理計算機上，你只需要從 <code>esp</code> 目錄中複製文件到計算機上已存在的 EFI 系統分區中。你不需要使用 <code>uefi.img</code> 文件去引導物理計算機。</p><p>注意：在一個物理計算機上，如果文件名已存在，你可以重命名 <code>bootx64.efi</code> 文件，如果你重命名了它，就需要去編輯計算機的 BIOS 設置，並添加重命令後的 efi 文件到引導列表中。</p></blockquote><p>接下來我們需要去安裝 qemu 包：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ dnf install -y qemu-system-x86</span></span></code></pre></div><p>允許 QEMU 訪問我們在本教程“初始化配置”一節中創建的網橋：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ echo &#39;allow br0&#39; &gt; /etc/qemu/bridge.conf</span></span></code></pre></div><p>創建一個 <code>OVMF_VARS.fd</code> 鏡像的副本去保存我們虛擬機的持久 BIOS 配置：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cp /usr/share/edk2/ovmf/OVMF_VARS.fd $HOME</span></span></code></pre></div><p>現在，啓動虛擬機：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ qemu-system-x86_64 -machine accel=kvm -nographic -m 1024 -drive if=pflash,format=raw,unit=0,file=/usr/share/edk2/ovmf/OVMF_CODE.fd,readonly=on -drive if=pflash,format=raw,unit=1,file=$HOME/OVMF_VARS.fd -drive if=ide,format=raw,file=$HOME/uefi.img -net bridge,br=br0 -net nic,model=virtio</span></span></code></pre></div><p>如果一切順利，你將看到類似下圖所示的結果：</p><p><img src="https://fedoramagazine.org/wp-content/uploads/2018/11/netboot-liveuser-1024x641.png" alt=""></p><p>你可以使用 <code>shutdown</code> 命令關閉虛擬機回到我們的服務器上：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo shutdown -h now</span></span></code></pre></div><blockquote><p>注意：如果出現了錯誤或虛擬機掛住了，你可能需要啓動一個新的 SSH 會話去連接服務器，使用 <code>kill</code> 命令去終止 <code>qemu-system-x86_64</code> 進程。</p></blockquote><h3 id="鏡像中添加包" tabindex="-1">鏡像中添加包 <a class="header-anchor" href="#鏡像中添加包" aria-label="Permalink to “鏡像中添加包”">​</a></h3><p>鏡像中添加包應該是一個很簡單的問題，在服務器上 <code>chroot</code> 進鏡像，然後運行 <code>dnf install &lt;package_name&gt;</code>。</p><p>在網絡引導鏡像中並不限制你能安裝什麼包。一個完整的圖形化安裝應該能夠完美地工作。</p><p>下面是一個如何將最小化安裝的網絡引導鏡像變成完整的圖形化安裝的示例：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ for i in dev dev/pts dev/shm proc sys run; do mount -o bind /$i /fc28/$i; done</span></span>
<span class="line"><span>$ chroot /fc28 /usr/bin/bash --login</span></span>
<span class="line"><span>$ dnf -y groupinstall &quot;Fedora Workstation&quot;</span></span>
<span class="line"><span>$ dnf -y remove gnome-initial-setup</span></span>
<span class="line"><span>$ systemctl disable sshd.service</span></span>
<span class="line"><span>$ systemctl enable gdm.service</span></span>
<span class="line"><span>$ systemctl set-default graphical.target</span></span>
<span class="line"><span>$ sed -i &#39;s/SELINUX=enforcing/SELINUX=disabled/&#39; /etc/sysconfig/selinux</span></span>
<span class="line"><span>$ logout</span></span>
<span class="line"><span>$ for i in run sys proc dev/shm dev/pts dev; do umount /fc28/$i; done</span></span></code></pre></div><p>可選地，你可能希望去啓用 <code>liveuser</code> 用户的自動登錄：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sed -i &#39;/daemon/a AutomaticLoginEnable=true&#39; /fc28/etc/gdm/custom.conf</span></span>
<span class="line"><span>$ sed -i &#39;/daemon/a AutomaticLogin=liveuser&#39; /fc28/etc/gdm/custom.conf</span></span></code></pre></div><hr>`,40)),n("p",null,[s[28]||(s[28]=a("via: ",-1)),e(i,{href:"https://fedoramagazine.org/how-to-build-a-netboot-server-part-1/"},{default:t(()=>[...s[27]||(s[27]=[a("https://fedoramagazine.org/how-to-build-a-netboot-server-part-1/",-1)])]),_:1})]),n("p",null,[s[33]||(s[33]=a("作者：",-1)),e(i,{href:"https://fedoramagazine.org/author/glb/"},{default:t(()=>[...s[29]||(s[29]=[a("Gregory Bartholomew",-1)])]),_:1}),s[34]||(s[34]=a(" 選題：",-1)),e(i,{href:"https://github.com/lujun9972"},{default:t(()=>[...s[30]||(s[30]=[a("lujun9972",-1)])]),_:1}),s[35]||(s[35]=a(" 譯者：",-1)),e(i,{href:"https://github.com/qhwdw"},{default:t(()=>[...s[31]||(s[31]=[a("qhwdw",-1)])]),_:1}),s[36]||(s[36]=a(" 校對：",-1)),e(i,{href:"https://github.com/wxy"},{default:t(()=>[...s[32]||(s[32]=[a("wxy",-1)])]),_:1})]),n("p",null,[s[39]||(s[39]=a("本文由 ",-1)),e(i,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...s[37]||(s[37]=[a("LCTT",-1)])]),_:1}),s[40]||(s[40]=a(" 原創編譯，",-1)),e(i,{href:"https://linux.cn/"},{default:t(()=>[...s[38]||(s[38]=[a("Linux中國",-1)])]),_:1}),s[41]||(s[41]=a(" 榮譽推出",-1))])])}const v=p(c,[["render",h]]);export{$ as __pageData,v as default};
